alter table public.products add column if not exists control_serial boolean not null default false;
create table public.product_serials(id uuid primary key default gen_random_uuid(),variant_id uuid not null references public.product_variants(id),location_id uuid not null references public.locations(id),serial_number text not null,imei2 text,estado text not null default 'disponible' check(estado in('disponible','vendido','en_transito','servicio','baja')),sale_id uuid references public.sales(id),recepcion_item_id uuid references public.recepcion_compra_items(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),sold_at timestamptz,unique(serial_number));
create unique index product_serials_imei2_uq on public.product_serials(imei2) where imei2 is not null and btrim(imei2)<>'';
create table public.sale_item_serials(sale_item_id uuid not null references public.sale_items(id) on delete cascade,serial_id uuid not null unique references public.product_serials(id),primary key(sale_item_id,serial_id));
create table public.transferencia_stock_serials(transferencia_id uuid not null references public.transferencias_stock(id) on delete cascade,serial_id uuid not null unique references public.product_serials(id),primary key(transferencia_id,serial_id));
alter table public.product_serials enable row level security;alter table public.sale_item_serials enable row level security;alter table public.transferencia_stock_serials enable row level security;
create policy serials_read on public.product_serials for select to authenticated using(private.auth_is_admin() or location_id=private.auth_location_id());
create policy sale_item_serials_read on public.sale_item_serials for select to authenticated using(exists(select 1 from public.sale_items si join public.sales s on s.id=si.sale_id where si.id=sale_item_id and(private.auth_is_admin() or s.location_id=private.auth_location_id())));
create policy transfer_serials_read on public.transferencia_stock_serials for select to authenticated using(exists(select 1 from public.transferencias_stock t where t.id=transferencia_id and(private.auth_is_admin() or t.origen_id=private.auth_location_id() or t.destino_id=private.auth_location_id())));
create or replace function public.seriales_disponibles(p_variant_id uuid) returns table(id uuid,serial_number text,imei2 text) language sql stable security invoker set search_path='public','private' as $$select ps.id,ps.serial_number,ps.imei2 from public.product_serials ps where ps.variant_id=p_variant_id and ps.location_id=private.auth_location_id() and ps.estado='disponible' order by ps.serial_number$$;
grant execute on function public.seriales_disponibles(uuid) to authenticated;
create or replace function public.registrar_seriales(p_variant_id uuid,p_seriales jsonb) returns integer language plpgsql security definer set search_path='public','private' as $$declare s public.staff;x jsonb;v_count int:=0;v_stock int;v_control boolean;begin select * into s from public.staff where user_id=auth.uid() and activo=true limit 1;if s.id is null or not(s.rol='administrador' or s.puesto in('tecnico','encargado','jefa')) then raise exception 'Sin permiso';end if;select p.control_serial into v_control from public.product_variants pv join public.products p on p.id=pv.product_id where pv.id=p_variant_id;if not coalesce(v_control,false) then raise exception 'El producto no usa control por serie';end if;select coalesce(cantidad,0) into v_stock from public.inventory where variant_id=p_variant_id and location_id=s.location_id;for x in select * from jsonb_array_elements(p_seriales) loop insert into public.product_serials(variant_id,location_id,serial_number,imei2) values(p_variant_id,s.location_id,btrim(x->>'serial_number'),nullif(btrim(x->>'imei2'),''));v_count:=v_count+1;end loop;if (select count(*) from public.product_serials where variant_id=p_variant_id and location_id=s.location_id and estado='disponible')>v_stock then raise exception 'Hay más seriales disponibles que stock físico';end if;return v_count;end$$;
grant execute on function public.registrar_seriales(uuid,jsonb) to authenticated;
create or replace function public.registrar_venta_serializada(p_items jsonb,p_pagos jsonb,p_subtotal numeric,p_impuesto numeric,p_total numeric,p_client_transaction_id uuid default null,p_cliente_id uuid default null,p_cliente_doc text default null,p_location_id uuid default null,p_cajero_id uuid default null,p_cash_session_id uuid default null,p_tipo_comprobante text default 'boleta',p_comprobante_cliente_tipo_doc text default null,p_comprobante_cliente_num_doc text default null,p_comprobante_cliente_denominacion text default null,p_comprobante_cliente_direccion text default null) returns public.sales language plpgsql security definer set search_path='public','private' as $$declare v_sale public.sales;x jsonb;v_variant uuid;v_qty int;v_control boolean;v_serials jsonb;v_si uuid;v_existing int;sid text;v_ps uuid;begin v_sale:=public.registrar_venta(p_items,p_pagos,p_subtotal,p_impuesto,p_total,p_client_transaction_id,p_cliente_id,p_cliente_doc,p_location_id,p_cajero_id,p_cash_session_id,p_tipo_comprobante,p_comprobante_cliente_tipo_doc,p_comprobante_cliente_num_doc,p_comprobante_cliente_denominacion,p_comprobante_cliente_direccion);for x in select * from jsonb_array_elements(p_items) loop v_variant:=(x->>'variant_id')::uuid;v_qty:=(x->>'cantidad')::int;select p.control_serial into v_control from public.product_variants pv join public.products p on p.id=pv.product_id where pv.id=v_variant;v_serials:=coalesce(x->'serial_ids','[]'::jsonb);select id into v_si from public.sale_items where sale_id=v_sale.id and variant_id=v_variant order by id limit 1;if coalesce(v_control,false) then if jsonb_array_length(v_serials)<>v_qty then raise exception 'Debes seleccionar exactamente % serial(es) para el producto',v_qty;end if;select count(*) into v_existing from public.sale_item_serials where sale_item_id=v_si;if v_existing=v_qty then continue;elsif v_existing>0 then raise exception 'Asignación serial incompleta previa';end if;for sid in select jsonb_array_elements_text(v_serials) loop update public.product_serials set estado='vendido',sale_id=v_sale.id,sold_at=now(),updated_at=now() where id=sid::uuid and variant_id=v_variant and location_id=v_sale.location_id and estado='disponible' returning id into v_ps;if v_ps is null then raise exception 'Serial no disponible o no pertenece a esta sucursal';end if;insert into public.sale_item_serials(sale_item_id,serial_id) values(v_si,v_ps);end loop;elsif jsonb_array_length(v_serials)>0 then raise exception 'El producto no requiere serial';end if;end loop;return v_sale;end$$;
grant execute on function public.registrar_venta_serializada(jsonb,jsonb,numeric,numeric,numeric,uuid,uuid,text,uuid,uuid,uuid,text,text,text,text,text) to authenticated;

create or replace function public.recibir_orden_compra(p_orden_id uuid,p_items jsonb,p_observacion text default null) returns public.recepciones_compra language plpgsql security definer set search_path='public','private' as $$declare v_staff public.staff;v_orden public.ordenes_compra;v_rec public.recepciones_compra;x jsonb;v_item public.orden_compra_items;v_qty int;v_pend int;v_control boolean;v_seriales jsonb;sx jsonb;v_ri uuid;begin select * into v_staff from public.staff where user_id=auth.uid() and activo=true limit 1;if v_staff.id is null or not(v_staff.rol='administrador' or v_staff.puesto in('tecnico','encargado','jefa')) then raise exception 'Sin permiso para recibir compras';end if;select * into v_orden from public.ordenes_compra where id=p_orden_id for update;if v_orden.id is null or v_orden.location_id<>v_staff.location_id then raise exception 'Orden inválida o de otra sucursal';end if;if v_orden.estado in('recibida','cancelada') then raise exception 'Orden no recepcionable';end if;if p_items is null or jsonb_array_length(p_items)=0 then raise exception 'Recepción vacía';end if;insert into public.recepciones_compra(orden_id,recibido_por,observacion) values(v_orden.id,v_staff.id,nullif(btrim(p_observacion),'')) returning * into v_rec;for x in select * from jsonb_array_elements(p_items) loop select * into v_item from public.orden_compra_items where id=(x->>'orden_item_id')::uuid and orden_id=v_orden.id for update;if v_item.id is null then raise exception 'Línea inválida';end if;v_qty:=(x->>'cantidad')::int;if v_qty<=0 or v_item.cantidad_recibida+v_qty>v_item.cantidad_pedida then raise exception 'Cantidad excede pendiente';end if;select p.control_serial into v_control from public.product_variants pv join public.products p on p.id=pv.product_id where pv.id=v_item.variant_id;v_seriales:=coalesce(x->'seriales','[]'::jsonb);if coalesce(v_control,false) and jsonb_array_length(v_seriales)<>v_qty then raise exception 'La recepción requiere % serial(es)',v_qty;end if;insert into public.recepcion_compra_items(recepcion_id,orden_item_id,cantidad,costo_unitario) values(v_rec.id,v_item.id,v_qty,v_item.costo_unitario) returning id into v_ri;update public.orden_compra_items set cantidad_recibida=cantidad_recibida+v_qty where id=v_item.id;insert into public.inventory(variant_id,location_id,cantidad) values(v_item.variant_id,v_orden.location_id,v_qty) on conflict(variant_id,location_id) do update set cantidad=public.inventory.cantidad+excluded.cantidad,updated_at=now();insert into public.inventory_movements(variant_id,location_id,cantidad_delta,motivo,staff_id) values(v_item.variant_id,v_orden.location_id,v_qty,'Recepción compra #'||v_orden.numero,v_staff.id);if coalesce(v_control,false) then for sx in select * from jsonb_array_elements(v_seriales) loop insert into public.product_serials(variant_id,location_id,serial_number,imei2,recepcion_item_id) values(v_item.variant_id,v_orden.location_id,btrim(sx->>'serial_number'),nullif(btrim(sx->>'imei2'),''),v_ri);end loop;end if;end loop;select count(*) into v_pend from public.orden_compra_items where orden_id=v_orden.id and cantidad_recibida<cantidad_pedida;update public.ordenes_compra set estado=case when v_pend=0 then 'recibida' else 'parcial' end,updated_at=now() where id=v_orden.id;return v_rec;end$$;

create or replace function public.crear_transferencia_stock(p_destino_id uuid,p_items jsonb,p_observacion text default null) returns public.transferencias_stock language plpgsql security definer set search_path='public','private' as $$declare s public.staff;t public.transferencias_stock;x jsonb;v_control boolean;v_serials jsonb;sid text;v_qty int;begin if not private.auth_is_admin() then raise exception 'Solo administradores';end if;select * into s from public.staff where user_id=auth.uid() and activo=true limit 1;if s.id is null then raise exception 'Personal inválido';end if;if p_destino_id=s.location_id then raise exception 'Origen y destino no pueden ser iguales';end if;if p_items is null or jsonb_array_length(p_items)=0 then raise exception 'Transferencia vacía';end if;insert into public.transferencias_stock(origen_id,destino_id,creado_por,observacion) values(s.location_id,p_destino_id,s.id,nullif(btrim(p_observacion),'')) returning * into t;for x in select * from jsonb_array_elements(p_items) loop v_qty:=(x->>'cantidad')::int;insert into public.transferencia_stock_items(transferencia_id,variant_id,cantidad) values(t.id,(x->>'variant_id')::uuid,v_qty);select p.control_serial into v_control from public.product_variants pv join public.products p on p.id=pv.product_id where pv.id=(x->>'variant_id')::uuid;v_serials:=coalesce(x->'serial_ids','[]'::jsonb);if coalesce(v_control,false) then if jsonb_array_length(v_serials)<>v_qty then raise exception 'Transferencia requiere seriales exactos';end if;for sid in select jsonb_array_elements_text(v_serials) loop if not exists(select 1 from public.product_serials where id=sid::uuid and variant_id=(x->>'variant_id')::uuid and location_id=s.location_id and estado='disponible') then raise exception 'Serial no disponible';end if;insert into public.transferencia_stock_serials(transferencia_id,serial_id) values(t.id,sid::uuid);end loop;elsif jsonb_array_length(v_serials)>0 then raise exception 'Producto sin control serial';end if;end loop;return t;end$$;

create or replace function public.despachar_transferencia_stock(p_transferencia_id uuid) returns public.transferencias_stock language plpgsql security definer set search_path='public','private' as $$declare s public.staff;t public.transferencias_stock;i public.transferencia_stock_items;begin select * into s from public.staff where user_id=auth.uid() and activo=true limit 1;if s.id is null or not(s.rol='administrador' or s.puesto in('tecnico','encargado','jefa')) then raise exception 'Sin permiso';end if;select * into t from public.transferencias_stock where id=p_transferencia_id for update;if t.id is null or t.origen_id<>s.location_id or t.estado<>'borrador' then raise exception 'Transferencia no despachable';end if;for i in select * from public.transferencia_stock_items where transferencia_id=t.id loop update public.inventory set cantidad=cantidad-i.cantidad,updated_at=now() where variant_id=i.variant_id and location_id=t.origen_id and cantidad>=i.cantidad;if not found then raise exception 'Stock insuficiente para transferencia';end if;insert into public.inventory_movements(variant_id,location_id,cantidad_delta,motivo,staff_id) values(i.variant_id,t.origen_id,-i.cantidad,'Transferencia # '||t.numero||' despachada',s.id);end loop;update public.product_serials ps set estado='en_transito',updated_at=now() from public.transferencia_stock_serials ts where ts.transferencia_id=t.id and ts.serial_id=ps.id and ps.location_id=t.origen_id and ps.estado='disponible';update public.transferencias_stock set estado='en_transito',despachado_por=s.id,fecha_despacho=now() where id=t.id returning * into t;return t;end$$;

create or replace function public.recibir_transferencia_stock(p_transferencia_id uuid) returns public.transferencias_stock language plpgsql security definer set search_path='public','private' as $$declare s public.staff;t public.transferencias_stock;i public.transferencia_stock_items;begin select * into s from public.staff where user_id=auth.uid() and activo=true limit 1;if s.id is null or not(s.rol='administrador' or s.puesto in('tecnico','encargado','jefa')) then raise exception 'Sin permiso';end if;select * into t from public.transferencias_stock where id=p_transferencia_id for update;if t.id is null or t.destino_id<>s.location_id or t.estado<>'en_transito' then raise exception 'Transferencia no recibible';end if;for i in select * from public.transferencia_stock_items where transferencia_id=t.id loop insert into public.inventory(variant_id,location_id,cantidad) values(i.variant_id,t.destino_id,i.cantidad) on conflict(variant_id,location_id) do update set cantidad=public.inventory.cantidad+excluded.cantidad,updated_at=now();insert into public.inventory_movements(variant_id,location_id,cantidad_delta,motivo,staff_id) values(i.variant_id,t.destino_id,i.cantidad,'Transferencia # '||t.numero||' recibida',s.id);end loop;update public.product_serials ps set estado='disponible',location_id=t.destino_id,updated_at=now() from public.transferencia_stock_serials ts where ts.transferencia_id=t.id and ts.serial_id=ps.id and ps.estado='en_transito';update public.transferencias_stock set estado='recibida',recibido_por=s.id,fecha_recepcion=now() where id=t.id returning * into t;return t;end$$;

create or replace function public.cerrar_inventario_fisico(p_inventario_id uuid) returns public.inventarios_fisicos language plpgsql security definer set search_path='public','private' as $$declare s public.staff;f public.inventarios_fisicos;i public.inventario_fisico_items;v_control boolean;begin select * into s from public.staff where user_id=auth.uid() and activo=true limit 1;if s.id is null or not(s.rol='administrador' or s.puesto in('encargado','jefa')) then raise exception 'Solo administración/encargado puede cerrar conteo';end if;select * into f from public.inventarios_fisicos where id=p_inventario_id for update;if f.id is null or f.location_id<>s.location_id or f.estado<>'abierto' then raise exception 'Conteo no cerrable';end if;if exists(select 1 from public.inventario_fisico_items where inventario_id=f.id and cantidad_contada is null) then raise exception 'Faltan productos por contar';end if;for i in select * from public.inventario_fisico_items where inventario_id=f.id and diferencia<>0 loop select p.control_serial into v_control from public.product_variants pv join public.products p on p.id=pv.product_id where pv.id=i.variant_id;if coalesce(v_control,false) then raise exception 'Producto serializado con diferencia: reconcilia IMEI/series antes de cerrar';end if;insert into public.inventory(variant_id,location_id,cantidad) values(i.variant_id,f.location_id,i.cantidad_contada) on conflict(variant_id,location_id) do update set cantidad=excluded.cantidad,updated_at=now();insert into public.inventory_movements(variant_id,location_id,cantidad_delta,motivo,staff_id) values(i.variant_id,f.location_id,i.diferencia,'Ajuste conteo físico',s.id);end loop;update public.inventarios_fisicos set estado='cerrado',cerrado_por=s.id,fecha_cierre=now() where id=f.id returning * into f;return f;end$$;
create trigger audit_product_serials after insert or update or delete on public.product_serials for each row execute function private.registrar_auditoria();